/* V1.4: one visible capsule height; any interaction retains a separate 44px target. */
#app .v13-state-status,#app .v13-state-status.failure,#app .v13-state-meta{height:32px;min-height:32px;max-height:32px;box-sizing:border-box;display:flex;align-items:center;padding:0 10px;border-radius:16px;white-space:nowrap;overflow:visible;font-variant-numeric:tabular-nums}
#app .v13-state-retry{height:32px;min-height:32px;width:auto;min-width:0;padding:0;font:600 12px/1.4 -apple-system,sans-serif;margin:0;position:relative;overflow:visible}
